#include <sys/mman.h>

void prefetch(const void *p) { __builtin_prefetch(p, 0, 1); }   // read, keep in L3
void prefetch_l1(const void *p) { __builtin_prefetch(p, 0, 3); } // read, keep in L1
void prefetch_nta(const void *p) { __builtin_prefetch(p, 0, 0); } // read once: evict early

/* pointer chase: prefetch the node body one level ahead */
for (size_t i = 0; i < n; i++) {
    node = node->next;
    __builtin_prefetch(node, 0, 1);      /* L3: fetched now, used after the next compare */
    sum += node->value;
}

/* page-level: fault the region in before the sensitive section */
